namespace
{

// Nominal uncontended timings for the instruction forms rewritten below.
// Generated by tools/gen_z80_tables.py from the bundled opcode reference.
using z80gen::kB_Call;
using z80gen::kB_IncDecPair;
using z80gen::kB_IncDecReg;
using z80gen::kB_Jp;
using z80gen::kB_LdPairImm;
using z80gen::kB_LdRegImm;
using z80gen::kB_LdRegReg;
using z80gen::kB_LogicalA;
using z80gen::kB_Ret;
using z80gen::kT_Call;
using z80gen::kT_IncDecPair;
using z80gen::kT_IncDecReg;
using z80gen::kT_Jp;
using z80gen::kT_LdPairImm;
using z80gen::kT_LdRegImm;
using z80gen::kT_LdRegReg;
using z80gen::kT_LogicalA;
using z80gen::kT_Ret;

const char* const kRegName[8] = {"b", "c", "d", "e", "h", "l", "(hl)", "a"};
const char* const kPairName[4] = {"bc", "de", "hl", "sp"};
// Byte-register indices of each pair's halves, in kRegName order.
const int kPairHi[4] = {0, 2, 4, -1}; // b, d, h, (sp has none)
const int kPairLo[4] = {1, 3, 5, -1};

// Which byte register an `ld r,n` / `ld r,r'` field names. Index 6 is (HL) -
// memory, not a register, and every rule below refuses it.
bool IsByteReg(int Idx)
{
	return Idx >= 0 && Idx < 8 && Idx != 6;
}

// `ld r,n`   : 00 rrr 110
bool IsLdRegImm(uint8_t Op)
{
	return (Op & 0xC7) == 0x06;
}
// `ld r,r'`  : 01 rrr rrr, except $76 (halt)
bool IsLdRegReg(uint8_t Op)
{
	return (Op & 0xC0) == 0x40 && Op != 0x76;
}
// `ld rr,nn` : 00 rr 0001
bool IsLdPairImm(uint8_t Op)
{
	return (Op & 0xCF) == 0x01;
}
// `inc rr` : 00 rr 0011   `dec rr` : 00 rr 1011
bool IsIncPair(uint8_t Op)
{
	return (Op & 0xCF) == 0x03;
}
bool IsDecPair(uint8_t Op)
{
	return (Op & 0xCF) == 0x0B;
}

// `call nn` unconditional, or `call cc,nn` : 11 ccc 100
bool IsCall(uint8_t Op)
{
	return Op == 0xCD || (Op & 0xC7) == 0xC4;
}

// Branches that test ONLY carry. This is what makes the redundant-flag-reset
// rule usable: `or a` clears carry but also sets S/Z/P, and the overwhelmingly
// common use is `ld a,h : or a : jr z` -- a ZERO test, where the instruction is
// load-bearing and dropping it would break the code. Reporting is therefore
// restricted to the case where the very next instruction consumes carry and
// nothing else, i.e. the reset really was there for the carry.
bool IsCarryOnlyBranch(uint8_t Op)
{
	return Op == 0x30 || Op == 0x38 // jr nc / jr c
		   || Op == 0xD2 || Op == 0xDA // jp nc / jp c
		   || Op == 0xD0 || Op == 0xD8 // ret nc / ret c
		   || Op == 0xD4 || Op == 0xDC; // call nc / call c
}

int DstReg(uint8_t Op)
{
	return (Op >> 3) & 7;
}
int SrcReg(uint8_t Op)
{
	return Op & 7;
}
int PairIdx(uint8_t Op)
{
	return (Op >> 4) & 3;
}

} // namespace

// Byte-register value out of a frame's PRE state, indexed like the opcode field.
static bool PreReg8(
	const PeepholeAnalyzer::RuleId, int Idx, uint16_t AF, uint16_t BC, uint16_t DE, uint16_t HL, uint8_t& Out)
{
	switch (Idx)
	{
	case 0:
		Out = uint8_t(BC >> 8);
		return true; // b
	case 1:
		Out = uint8_t(BC);
		return true; // c
	case 2:
		Out = uint8_t(DE >> 8);
		return true; // d
	case 3:
		Out = uint8_t(DE);
		return true; // e
	case 4:
		Out = uint8_t(HL >> 8);
		return true; // h
	case 5:
		Out = uint8_t(HL);
		return true; // l
	case 7:
		Out = uint8_t(AF >> 8);
		return true; // a
	default:
		return false; // 6 = (hl)
	}
}

static uint16_t PrePair(int Idx, uint16_t BC, uint16_t DE, uint16_t HL, uint16_t SP)
{
	switch (Idx)
	{
	case 0:
		return BC;
	case 1:
		return DE;
	case 2:
		return HL;
	default:
		return SP;
	}
}

bool PeepholeAnalyzer::ByteWritten(uint8_t PageTag, uint16_t PC, int Index, uint64_t SinceCycle) const
{
	const uint16_t A = uint16_t(PC + Index);
	if ((A >> 13) == (PC >> 13))
	{
		// Same 8K slot as the opcode, so the instruction's page applies: exact.
		const auto It = m_WrittenBytes.find(ByteKey(PageTag, A));
		return It != m_WrittenBytes.end() && It->second >= SinceCycle;
	}
	// Straddles into the next slot, whose page at execution time is not
	// recoverable here. Fall back to "was this offset written in ANY page".
	const auto It = m_WrittenOffsetsAnyPage.find(uint16_t(A & 0x1FFF));
	return It != m_WrittenOffsetsAnyPage.end() && It->second >= SinceCycle;
}

int PeepholeAnalyzer::FirstWrittenByte(uint32_t Site) const
{
	const auto It = m_SiteLen.find(Site);
	const uint8_t Page = uint8_t(Site >> 16);
	const uint16_t kPC = uint16_t(Site & 0xFFFF);
	const int Len = (It != m_SiteLen.end() && It->second > 0) ? It->second : 1;
	// Only writes from this site's first execution onwards count; anything
	// earlier put the code there in the first place.
	const auto FIt = m_SiteFirstExec.find(Site);
	const uint64_t Since = (FIt != m_SiteFirstExec.end()) ? FIt->second : 0;
	for (int IdxI = 0; IdxI < Len; ++IdxI)
	{
		if (ByteWritten(Page, kPC, IdxI, Since))
		{
			return IdxI;
		}
	}
	return -1;
}

bool PeepholeAnalyzer::SiteWasWritten(uint32_t Site) const
{
	if (m_WrittenBytes.empty())
	{
		return false;
	}
	const auto It = m_SiteLen.find(Site);
	const uint8_t Page = uint8_t(Site >> 16);
	const uint16_t kPC = uint16_t(Site & 0xFFFF);
	const int Len = (It != m_SiteLen.end() && It->second > 0) ? It->second : 1;
	const auto FIt = m_SiteFirstExec.find(Site);
	const uint64_t Since = (FIt != m_SiteFirstExec.end()) ? FIt->second : 0;
	for (int IdxI = 0; IdxI < Len; ++IdxI)
	{
		if (ByteWritten(Page, kPC, IdxI, Since))
		{
			return true;
		}
	}
	return false;
}

void PeepholeAnalyzer::Record(RuleId R, const Slot& S, int32_t SaveT, int32_t SaveB, std::string Text, bool bPair,
	bool bAdjacent, uint32_t Partner)
{
	// No win on either axis is not a finding. This is what keeps a rewrite that
	// costs time and saves nothing out of the report entirely.
	if (SaveT <= 0 && SaveB <= 0)
	{
		return;
	}

	Finding& F = m_Findings[KeyOf(S.m_Page, S.PC, uint8_t(R))];
	if (F.m_Hits == 0)
	{
		F.m_Rule = uint8_t(R);
		F.m_Page = S.m_Page;
		F.PC = S.PC;
		F.m_SaveT = SaveT;
		F.m_SaveB = SaveB;
		F.m_Text = std::move(Text);
		F.m_bPair = bPair;
		F.m_Partner = Partner;
		F.m_Len = S.m_Len;
	}
	// A site reached both ways takes the weaker classification.
	if (!bAdjacent)
	{
		F.m_bAllAdj = false;
	}
	++F.m_Hits;
}

void PeepholeAnalyzer::Feed(const TraceFrame& TF)
{
	using namespace BinaryTrace;

	// Only real instruction records carry a register snapshot. Interrupts,
	// DMA drips and the v4 video-state events do not describe code that could
	// be rewritten, and feeding them would corrupt the adjacency chain.
	if (TF.m_Flags & (TraceFrame::kFlagInterrupt | TraceFrame::kFlagInvalid | TraceFrame::kFlagResetTrap |
						 TraceFrame::kFlagDma | TraceFrame::kFlagStateWrite | TraceFrame::kFlagInput))
	{
		m_Prev.m_bValid = false; // control left the straight-line path
		for (int P = 0; P < 3; ++P)
		{
			ResetSeries(P);
		}
		return;
	}

	Slot S;
	S.PC = TF.m_PrePC;
	S.m_PostPC = TF.m_PostPC;
	S.m_Page = TF.m_PrePageTag;
	memcpy(S.m_Op, TF.m_OpcodeBytes, 4);
	char Mnem[64];
	S.m_Len = uint8_t(Disassemble(S.m_Op, S.PC, Mnem, sizeof(Mnem), nullptr));
	S.m_PreAF = TF.m_PreAF;
	S.m_PreBC = TF.m_PreBC;
	S.m_PreDE = TF.m_PreDE;
	S.m_PreHL = TF.m_PreHL;
	S.m_PostAF = TF.m_PostAF;
	S.m_PostBC = TF.m_PostBC;
	S.m_PostDE = TF.m_PostDE;
	S.m_PostHL = TF.m_PostHL;
	S.m_bValid = true;

	++m_NumInstructions;
	const uint32_t Site = SiteOf(S.m_Page, S.PC);
	++m_SiteExecs[Site];
	m_SiteOpcode[Site] = S.m_Op[0];
	m_SiteLen[Site] = S.m_Len;
	m_SiteFirstExec.emplace(Site, TF.m_StartCycles); // first execution only
	// Every byte this instruction wrote. Cheap: one bit per CPU address.
	for (uint8_t IdxI = 0; IdxI < TF.m_NumMemWrites && IdxI < 4; ++IdxI)
	{
		m_WrittenBytes[ByteKey(TF.m_MemWrites[IdxI].m_PageTag, TF.m_MemWrites[IdxI].m_Addr)] = TF.m_StartCycles;
		m_WrittenOffsetsAnyPage[uint16_t(TF.m_MemWrites[IdxI].m_Addr & 0x1FFF)] = TF.m_StartCycles;
	}
	m_SiteBytes[Site] = {S.m_Op[0], S.m_Op[1], S.m_Op[2], S.m_Op[3]};
	if (m_Prev.m_bValid)
	{
		const uint32_t PrevSite = SiteOf(m_Prev.m_Page, m_Prev.PC);
		if (m_Edges.insert((uint64_t(PrevSite) << 32) | uint64_t(Site)).second)
		{
			++m_PredCount[Site];
		}
	}

	const uint8_t Op = S.m_Op[0];

	// ---- single-instruction rules ------------------------------------------

	// xor a when A is already zero. The classic idiom is free when A is dirty;
	// this is the case where it is not.
	if (Op == 0xAF && uint8_t(S.m_PreAF >> 8) == 0)
	{
		Record(kRuleIdRuleRedundantLoad, S, kT_LogicalA, kB_LogicalA,
			"xor a  ->  (drop)   a is already $00 "
			"[also clears C and sets Z -- check they are dead]");
	}

	if (IsLdRegImm(Op))
	{
		const int Dst = DstReg(Op);
		uint8_t Cur = 0;
		if (IsByteReg(Dst) && PreReg8(kRuleIdRuleRedundantLoad, Dst, S.m_PreAF, S.m_PreBC, S.m_PreDE, S.m_PreHL, Cur))
		{
			const uint8_t Imm = S.m_Op[1];
			char Buf[160];
			if (Cur == Imm)
			{
				snprintf(Buf, sizeof(Buf), "ld %s,$%02X  ->  (drop)   %s already holds $%02X", kRegName[Dst], Imm,
					kRegName[Dst], Imm);
				Record(kRuleIdRuleRedundantLoad, S, kT_LdRegImm, kB_LdRegImm, Buf);
			}
			else
			{
				// +/-1 and +/-2: one or two inc/dec beat a 2-byte load on size,
				// and a single one beats it on speed too.
				const int Delta = int(Imm) - int(Cur);
				if (Delta == 1 || Delta == -1 || Delta == 2 || Delta == -2)
				{
					const int N = (Delta > 0) ? Delta : -Delta;
					const uint32_t T = kT_IncDecReg * uint32_t(N);
					const uint32_t B = kB_IncDecReg * uint32_t(N);
					if (T < kT_LdRegImm || B < kB_LdRegImm)
					{
						snprintf(Buf, sizeof(Buf),
							"ld %s,$%02X  ->  %s %s%s   (%s was $%02X) "
							"[8-bit inc/dec SETS FLAGS, ld does not]",
							kRegName[Dst], Imm, Delta > 0 ? "inc" : "dec", kRegName[Dst], N == 2 ? " x2" : "",
							kRegName[Dst], Cur);
						Record(kRuleIdRuleCouldBeIncDec, S, int32_t(kT_LdRegImm) - int32_t(T),
							int32_t(kB_LdRegImm) - int32_t(B), Buf);
					}
				}

				// The value may be sitting in another register already.
				for (int Src = 0; Src < 8; ++Src)
				{
					if (Src == Dst || !IsByteReg(Src))
					{
						continue;
					}
					uint8_t V = 0;
					if (!PreReg8(kRuleIdRuleValueInOtherReg, Src, S.m_PreAF, S.m_PreBC, S.m_PreDE, S.m_PreHL, V))
					{
						continue;
					}
					if (V != Imm)
					{
						continue;
					}
					snprintf(Buf, sizeof(Buf), "ld %s,$%02X  ->  ld %s,%s   (%s already holds $%02X)", kRegName[Dst],
						Imm, kRegName[Dst], kRegName[Src], kRegName[Src], Imm);
					Record(kRuleIdRuleValueInOtherReg, S, kT_LdRegImm - kT_LdRegReg, kB_LdRegImm - kB_LdRegReg, Buf);
					break;
				}
			}
		}
	}

	if (IsLdPairImm(Op))
	{
		const int Pair = PairIdx(Op);
		const bool bHasHalves = (kPairHi[Pair] >= 0); // false for SP
		const uint16_t Cur = PrePair(Pair, S.m_PreBC, S.m_PreDE, S.m_PreHL, TF.m_PreSP);
		const uint16_t Imm = uint16_t(S.m_Op[1] | (uint16_t(S.m_Op[2]) << 8));
		char Buf[160];
		if (Cur == Imm)
		{
			snprintf(Buf, sizeof(Buf), "ld %s,$%04X  ->  (drop)   %s already holds $%04X", kPairName[Pair], Imm,
				kPairName[Pair], Imm);
			Record(kRuleIdRuleRedundantLoad, S, kT_LdPairImm, kB_LdPairImm, Buf);
		}
		else
		{
			const int Delta = int(Imm) - int(Cur);
			const int N = (Delta > 0) ? Delta : -Delta;
			const bool bHiMatch = bHasHalves && (Cur >> 8) == (Imm >> 8);
			const bool bLoMatch = bHasHalves && (Cur & 0xFF) == (Imm & 0xFF);

			// Candidates in order of which is actually the better rewrite.
			// Getting this order wrong is not cosmetic: the half rule used to
			// come first and shadowed `inc de` (4T/2B) with a worse `ld e,n`
			// (3T/1B) at the same site.
			if (N == 1)
			{
				// 16-bit inc/dec touches no flags, so this needs no caveat.
				snprintf(Buf, sizeof(Buf), "ld %s,$%04X  ->  %s %s   (%s was $%04X)", kPairName[Pair], Imm,
					Delta > 0 ? "inc" : "dec", kPairName[Pair], kPairName[Pair], Cur);
				Record(kRuleIdRuleCouldBeIncDec, S, int32_t(kT_LdPairImm) - int32_t(kT_IncDecPair),
					int32_t(kB_LdPairImm) - int32_t(kB_IncDecPair), Buf);
			}
			else if (bHiMatch)
			{
				snprintf(Buf, sizeof(Buf), "ld %s,$%04X  ->  ld %s,$%02X   (%s already holds $%02X)", kPairName[Pair],
					Imm, kRegName[kPairLo[Pair]], uint8_t(Imm), kRegName[kPairHi[Pair]], uint8_t(Imm >> 8));
				Record(kRuleIdRuleHalfPairLoad, S, int32_t(kT_LdPairImm) - int32_t(kT_LdRegImm),
					int32_t(kB_LdPairImm) - int32_t(kB_LdRegImm), Buf);
			}
			else if (bLoMatch)
			{
				snprintf(Buf, sizeof(Buf), "ld %s,$%04X  ->  ld %s,$%02X   (%s already holds $%02X)", kPairName[Pair],
					Imm, kRegName[kPairHi[Pair]], uint8_t(Imm >> 8), kRegName[kPairLo[Pair]], uint8_t(Imm));
				Record(kRuleIdRuleHalfPairLoad, S, int32_t(kT_LdPairImm) - int32_t(kT_LdRegImm),
					int32_t(kB_LdPairImm) - int32_t(kB_LdRegImm), Buf);
			}
			else if (N == 2)
			{
				// Two inc/dec: a byte saved, two T-states lost. Signed, so it
				// lands in the size profile only.
				snprintf(Buf, sizeof(Buf), "ld %s,$%04X  ->  %s %s x2   (%s was $%04X)", kPairName[Pair], Imm,
					Delta > 0 ? "inc" : "dec", kPairName[Pair], kPairName[Pair], Cur);
				Record(kRuleIdRuleCouldBeIncDec, S, int32_t(kT_LdPairImm) - int32_t(kT_IncDecPair) * 2,
					int32_t(kB_LdPairImm) - int32_t(kB_IncDecPair) * 2, Buf);
			}
		}
	}

	// `ld r,r'` where both already hold the same value.
	if (IsLdRegReg(Op))
	{
		const int Dst = DstReg(Op), Src = SrcReg(Op);
		uint8_t A = 0, B = 0;
		if (IsByteReg(Dst) && IsByteReg(Src) &&
			PreReg8(kRuleIdRuleRedundantLoad, Dst, S.m_PreAF, S.m_PreBC, S.m_PreDE, S.m_PreHL, A) &&
			PreReg8(kRuleIdRuleRedundantLoad, Src, S.m_PreAF, S.m_PreBC, S.m_PreDE, S.m_PreHL, B) && A == B)
		{
			char Buf[160];
			snprintf(
				Buf, sizeof(Buf), "ld %s,%s  ->  (drop)   both already hold $%02X", kRegName[Dst], kRegName[Src], A);
			Record(kRuleIdRuleRedundantLoad, S, kT_LdRegReg, kB_LdRegReg, Buf);
		}
	}

	// `inc rr` -> `inc <lo>` where the carry into the high byte never happens.
	// 6T -> 4T at the same one byte, so a speed-only win.
	for (int P = 0; P < 3; ++P) // BC, DE, HL; SP has no addressable halves
	{
		const uint16_t PreV = PrePair(P, S.m_PreBC, S.m_PreDE, S.m_PreHL, TF.m_PreSP);
		const uint16_t PostV = PrePair(P, S.m_PostBC, S.m_PostDE, S.m_PostHL, TF.m_PostSP);
		const bool bThisPair = (IsIncPair(Op) || IsDecPair(Op)) && PairIdx(Op) == P;

		// Anything that changes the pair WITHOUT being an inc/dec of it starts
		// a fresh walk: a reload, a pop, an exchange, an add.
		if (PostV != PreV && !bThisPair)
		{
			ResetSeries(P);
			continue;
		}
		if (!bThisPair)
		{
			continue;
		}

		const uint8_t Lo = uint8_t(PreV);
		const bool bCarries = IsIncPair(Op) ? (Lo == 0xFF) : (Lo == 0x00);

		// Remember this site as part of the current walk (deduped; the same
		// sites recur every iteration).
		std::vector<uint32_t>& Sites = m_SeriesSites[P];
		bool bSeen = false;
		for (uint32_t X : Sites)
		{
			if (X == Site)
			{
				bSeen = true;
				break;
			}
		}
		if (!bSeen && int(Sites.size()) < kMaxSeriesSites)
		{
			Sites.push_back(Site);
		}

		if (bCarries)
		{
			// One crossing condemns the whole chain, not just this instruction:
			// the eight identical `inc de` lines of an unrolled walk are one
			// edit, and which of them happens to carry depends on alignment.
			m_bSeriesPoisoned[P] = true;
			for (uint32_t X : Sites)
			{
				m_PairCarrySites.insert(X);
			}
			m_PairCarrySites.insert(Site);
		}
		else if (m_bSeriesPoisoned[P])
		{
			m_PairCarrySites.insert(Site);
		}
		else
		{
			char Buf[200];
			snprintf(Buf, sizeof(Buf),
				"%s %s  ->  %s %s   (%s never carries here) "
				"[8-bit inc/dec SETS FLAGS, 16-bit does not]",
				IsIncPair(Op) ? "inc" : "dec", kPairName[P], IsIncPair(Op) ? "inc" : "dec", kRegName[kPairLo[P]],
				kPairName[P]);
			Record(kRuleIdRulePairIncNoCarry, S, int32_t(kT_IncDecPair) - int32_t(kT_IncDecReg), 0, Buf);
		}
	}

	// `call X : ret` -> `jp X`. Detected from the RET side: if an executed CALL
	// sits exactly where this RET's own address minus the call length lands,
	// the two are adjacent in memory and the tail call was never folded.
	if (Op == 0xC9)
	{
		const uint16_t CallPC = uint16_t(S.PC - 3);
		auto It = m_SiteOpcode.find(SiteOf(S.m_Page, CallPC));
		if (It != m_SiteOpcode.end() && IsCall(It->second))
		{
			char Buf[160];
			snprintf(Buf, sizeof(Buf), "call at $%04X then ret  ->  jp   (tail call not folded)", CallPC);
			Record(kRuleIdRuleCallRet, S, kT_Call + kT_Ret - kT_Jp, kB_Call + kB_Ret - kB_Jp, Buf);
		}
	}

	// ---- two-instruction rules ---------------------------------------------
	//
	// These fire on anything that ran back-to-back in the same execution
	// context. Whether the pair is also adjacent IN MEMORY is recorded, not
	// required: on a path the demo always takes, a redundant load is redundant
	// whether or not a jump sits between the two instructions. The report
	// carries the distinction so the fragile ones can be eyeballed first.
	const bool bLinked = m_Prev.m_bValid;
	const bool bAdjacent = m_Prev.m_bValid && m_Prev.m_Page == S.m_Page && m_Prev.m_PostPC == S.PC &&
						   uint16_t(m_Prev.PC + m_Prev.m_Len) == S.PC;
	const uint32_t ThisSite = SiteOf(S.m_Page, S.PC);

	// `or a` / `and a` that only had to clear carry -- and carry was already
	// clear. Gated on the next instruction being a carry-only branch, because
	// the same opcodes are overwhelmingly used as a zero test, where S/Z/P are
	// the whole point and dropping the instruction breaks the code.
	if (bLinked && (m_Prev.m_Op[0] == 0xB7 || m_Prev.m_Op[0] == 0xA7) && (m_Prev.m_PreAF & 0x01) == 0 &&
		IsCarryOnlyBranch(Op))
	{
		char Buf[160];
		snprintf(Buf, sizeof(Buf), "%s  ->  (drop)   carry already clear before a carry-only branch",
			m_Prev.m_Op[0] == 0xB7 ? "or a" : "and a");
		Record(kRuleIdRuleRedundantFlagReset, m_Prev, kT_LogicalA, kB_LogicalA, Buf, true, bAdjacent, ThisSite);
	}

	if (bLinked && IsLdRegImm(m_Prev.m_Op[0]) && IsLdRegImm(Op))
	{
		// Two halves of the same pair loaded separately.
		const int kD0 = DstReg(m_Prev.m_Op[0]), kD1 = DstReg(Op);
		static const int kHi[3] = {0, 2, 4}; // b, d, h
		static const int kLo[3] = {1, 3, 5}; // c, e, l
		for (int IdxI = 0; IdxI < 3; ++IdxI)
		{
			const bool bHiLo = (kD0 == kHi[IdxI] && kD1 == kLo[IdxI]);
			const bool bLoHi = (kD0 == kLo[IdxI] && kD1 == kHi[IdxI]);
			if (!bHiLo && !bLoHi)
			{
				continue;
			}
			const uint8_t HiV = bHiLo ? m_Prev.m_Op[1] : S.m_Op[1];
			const uint8_t LoV = bHiLo ? S.m_Op[1] : m_Prev.m_Op[1];
			char Buf[160];
			snprintf(Buf, sizeof(Buf), "ld %s,$%02X : ld %s,$%02X  ->  ld %s,$%04X", kRegName[kD0], m_Prev.m_Op[1],
				kRegName[kD1], S.m_Op[1], kPairName[IdxI], uint16_t((HiV << 8) | LoV));
			// Reported against the FIRST of the pair - that is the line to edit.
			Record(kRuleIdRuleSplitPairLoad, m_Prev, 2 * kT_LdRegImm - kT_LdPairImm, 2 * kB_LdRegImm - kB_LdPairImm,
				Buf, true, bAdjacent, ThisSite);
			break;
		}
	}

	// Returning from an interrupt lands back in unrelated mainline code, so the
	// ISR's last instruction must not pair with whatever it interrupted.
	if (S.m_Op[0] == 0xED && (S.m_Op[1] == 0x4D || S.m_Op[1] == 0x45))
	{
		m_Prev.m_bValid = false;
		return;
	}

	m_Prev = S;
}

bool PeepholeAnalyzer::WriteReport(const char* Path) const
{
	static const char* const kRuleName[kRuleIdRuleCount] = {
		"redundant load (register already holds the value)",
		"value already live in another register",
		"reachable by inc/dec from the current value",
		"register pair loaded in halves",
		"redundant flag reset (carry already clear)",
		"call followed by ret (tail call not folded)",
		"only half the register pair actually needs loading",
		"16-bit inc/dec whose walk never carries (8-bit form is 2T cheaper)",
	};
	FILE* OutFile = fopen(Path, "w");
	if (OutFile == nullptr)
	{
		return false;
	}

	fprintf(OutFile, "inspeccy peephole report\n");
	fprintf(OutFile, "instructions executed: %llu\n", (unsigned long long)m_NumInstructions);
	fprintf(OutFile, "consistency filter: pattern held on >= %.0f%% of executions\n", m_MinRatio * 100.0);
	fprintf(OutFile, "profile mask: %s%s\n", (m_ProfileMask & kProfileProfSpeed) ? "speed " : "",
		(m_ProfileMask & kProfileProfSize) ? "size" : "");
	fprintf(OutFile, "\nSavings are nominal uncontended T-states / bytes, multiplied by how\n"
					 "often the site ran. 'held' is how many of those executions matched --\n"
					 "anything below 100%% is value-dependent and needs a human look.\n"
					 "\nA value that merely HAPPENS to be right on entry is not safe to drop:\n"
					 "SP set by the loader, or a register left by whatever ran before, is a\n"
					 "coincidence of this path, not a guarantee. The report cannot tell that\n"
					 "from intent -- low run counts on setup code deserve the most suspicion.\n");

	// Rank by total T saved, then bytes: the top of this list is where an hour
	// of hand-optimisation actually pays.
	// Executions behind a finding: its own count when it carries one (merged
	// chains do), else the site's.
	const auto SiteExecCount = [&](const Finding* F) -> uint64_t
	{
		if (F->m_Execs != 0)
		{
			return F->m_Execs;
		}
		const auto I = m_SiteExecs.find(SiteOf(F->m_Page, F->PC));
		return (I != m_SiteExecs.end()) ? I->second : F->m_Hits;
	};

	std::vector<const Finding*> Sorted;
	Sorted.reserve(m_Findings.size());
	// Struck findings are LISTED, not just counted. A suppressed finding that
	// leaves no trace is indistinguishable from no finding at all, which reads
	// as "nothing to optimise here" -- the single most misleading thing this
	// report can say, and exactly what it said for a self-modifying intro.
	struct Struck
	{
		const Finding* m_F;
		int m_Byte;
		const char* m_Why;
	};
	std::vector<Struck> StruckList;
	for (const auto& kKV : m_Findings)
	{
		const Finding& Fi = kKV.second;
		// Derived per finding, so `--optimize-profile speed` cannot show a
		// rewrite that costs T-states just because its rule sometimes helps.
		if ((ProfileOf(Fi.m_SaveT, Fi.m_SaveB) & m_ProfileMask) == 0)
		{
			continue;
		}
		const auto It = m_SiteExecs.find(SiteOf(Fi.m_Page, Fi.PC));
		const uint64_t Execs = (It != m_SiteExecs.end()) ? It->second : Fi.m_Hits;
		if (Execs > 0 && double(Fi.m_Hits) / double(Execs) + 1e-9 < m_MinRatio)
		{
			continue;
		}
		// Struck, not flagged: if the instruction's own bytes were written at
		// any point in the run, its "constant" is a variable and the finding is
		// not fragile, it is wrong. Checked here, at the end, because the poke
		// can happen long after the site last ran.
		const int WrByte = FirstWrittenByte(SiteOf(Fi.m_Page, Fi.PC));
		if (WrByte >= 0)
		{
			StruckList.push_back({&Fi, WrByte, "byte rewritten after it first ran"});
			continue;
		}
		if (Fi.m_bPair && SiteWasWritten(Fi.m_Partner))
		{
			StruckList.push_back({&Fi, -1, "partner instruction was written"});
			continue;
		}
		if (Fi.m_Rule == kRuleIdRulePairIncNoCarry && m_PairCarrySites.count(SiteOf(Fi.m_Page, Fi.PC)) != 0)
		{
			StruckList.push_back({&Fi, -1, "the pair's walk crossed a byte boundary"});
			continue;
		}
		Sorted.push_back(&Fi);
	}
	// Rank by the axis actually being optimised for. Under `size` a one-byte
	// win on cold setup code outranks a T-state win that saves nothing.
	const bool bBySize = (m_ProfileMask == kProfileProfSize);
	// Half-poked immediates. When exactly ONE byte of a `ld rr,nn` operand is
	// ever written, the other half is a compile-time constant being reloaded on
	// every pass for nothing -- `ld de,FOO` where only E is ever poked should be
	// `ld e,BAR` with D set once outside. This can only be decided against the
	// whole run's write set, so it is synthesised here rather than in Feed.
	//
	// These sites are self-modified, so the strike above removed their other
	// findings; this is what replaces them.
	// deque, not vector: pointers into it are handed to Sorted below and the
	// merge pass appends more afterwards. A vector would reallocate and leave
	// every one of those pointers dangling.
	std::deque<Finding> Synth;
	for (const auto& kKV : m_SiteBytes)
	{
		const uint32_t Site = kKV.first;
		const uint8_t* Op = kKV.second.data();
		if (!IsLdPairImm(Op[0]))
		{
			continue;
		}
		const int Pair = PairIdx(Op[0]);
		if (kPairHi[Pair] < 0)
		{
			continue; // SP has no halves
		}

		const uint8_t Page = uint8_t(Site >> 16);
		const uint16_t kPC = uint16_t(Site & 0xFFFF);
		// Same cut as everywhere else: a poke before the code first ran was the
		// loader delivering it, not the program patching itself.
		const auto FIt = m_SiteFirstExec.find(Site);
		const uint64_t Since = (FIt != m_SiteFirstExec.end()) ? FIt->second : 0;
		const bool bLo = ByteWritten(Page, kPC, 1, Since); // operand low byte
		const bool bHi = ByteWritten(Page, kPC, 2, Since); // operand high byte
		if (bLo == bHi)
		{
			continue; // both or neither: nothing to say
		}

		const auto EIt = m_SiteExecs.find(Site);
		const uint64_t Execs = (EIt != m_SiteExecs.end()) ? EIt->second : 0;
		if (Execs == 0)
		{
			continue;
		}

		Finding F;
		F.m_Rule = uint8_t(kRuleIdRuleHalfPairLoad);
		F.m_Page = Page;
		F.PC = kPC;
		F.m_Len = 3;
		F.m_Hits = Execs; // holds on every execution
		F.m_SaveT = int32_t(kT_LdPairImm) - int32_t(kT_LdRegImm);
		F.m_SaveB = int32_t(kB_LdPairImm) - int32_t(kB_LdRegImm);

		char Buf[220];
		if (bLo)
		{
			snprintf(Buf, sizeof(Buf),
				"ld %s,nn  ->  ld %s,n   (only the LOW half is poked; "
				"high half $%02X is constant -- set %c once outside)",
				kPairName[Pair], kRegName[kPairLo[Pair]], Op[2], kRegName[kPairHi[Pair]][0]);
		}
		else
		{
			snprintf(Buf, sizeof(Buf),
				"ld %s,nn  ->  ld %s,n   (only the HIGH half is poked; "
				"low half $%02X is constant -- set %c once outside)",
				kPairName[Pair], kRegName[kPairHi[Pair]], Op[1], kRegName[kPairLo[Pair]][0]);
		}
		F.m_Text = Buf;
		if ((ProfileOf(F.m_SaveT, F.m_SaveB) & m_ProfileMask) == 0)
		{
			continue;
		}
		Synth.push_back(std::move(F));
	}
	for (const Finding& F : Synth)
	{
		Sorted.push_back(&F);
	}

	// Collapse an unrolled chain into one row. Eight identical `inc de` lines
	// in a row are ONE edit, not eight findings, and listing them separately
	// buries everything else. Merged only where the sites are literally
	// adjacent in memory, carry the same rule, and say the same thing -- which
	// is exactly the unrolled-walk shape and nothing else.
	{
		std::sort(Sorted.begin(), Sorted.end(),
			[](const Finding* A, const Finding* B)
			{
				if (A->m_Page != B->m_Page)
				{
					return A->m_Page < B->m_Page;
				}
				if (A->PC != B->PC)
				{
					return A->PC < B->PC;
				}
				return A->m_Rule < B->m_Rule;
			});
		std::vector<const Finding*> Merged;
		Merged.reserve(Sorted.size());
		for (size_t IdxI = 0; IdxI < Sorted.size();)
		{
			const Finding* Head = Sorted[IdxI];
			size_t IdxJ = IdxI + 1;
			while (IdxJ < Sorted.size() && Sorted[IdxJ]->m_Rule == Head->m_Rule &&
				   Sorted[IdxJ]->m_Page == Head->m_Page && Sorted[IdxJ]->m_Text == Head->m_Text &&
				   Sorted[IdxJ]->PC == uint16_t(Sorted[IdxJ - 1]->PC + Sorted[IdxJ - 1]->m_Len))
			{
				++IdxJ;
			}
			const size_t N = IdxJ - IdxI;
			if (N > 1)
			{
				Finding M = *Head;
				M.m_Execs = SiteExecCount(Head);
				for (size_t K = IdxI + 1; K < IdxJ; ++K)
				{
					M.m_Hits += Sorted[K]->m_Hits;
					M.m_Execs += SiteExecCount(Sorted[K]);
				}
				M.m_SaveB = int32_t(int64_t(M.m_SaveB) * int64_t(N));
				char Buf[260];
				snprintf(Buf, sizeof(Buf), "%s   [x%zu unrolled, $%04X..$%04X]", Head->m_Text.c_str(), N, Head->PC,
					uint16_t(Sorted[IdxJ - 1]->PC));
				M.m_Text = Buf;
				Synth.push_back(std::move(M));
				Merged.push_back(&Synth.back());
			}
			else
			{
				Merged.push_back(Head);
			}
			IdxI = IdxJ;
		}
		Sorted.swap(Merged);
	}

	std::sort(Sorted.begin(), Sorted.end(),
		[bBySize](const Finding* A, const Finding* B)
		{
			if (bBySize)
			{
				if (A->m_SaveB != B->m_SaveB)
				{
					return A->m_SaveB > B->m_SaveB;
				}
			}
			const int64_t kTA = int64_t(A->m_Hits) * A->m_SaveT;
			const int64_t kTB = int64_t(B->m_Hits) * B->m_SaveT;
			if (kTA != kTB)
			{
				return kTA > kTB;
			}
			return A->m_SaveB > B->m_SaveB;
		});

	// Only positive contributions: a size-win-speed-loss finding must not be
	// able to drag the headline T total downwards (or, before the sign fix,
	// upwards by four billion).
	uint64_t GrandT = 0, GrandB = 0;
	for (const Finding* Fi : Sorted)
	{
		if (Fi->m_SaveT > 0)
		{
			GrandT += Fi->m_Hits * uint64_t(Fi->m_SaveT);
		}
		if (Fi->m_SaveB > 0)
		{
			GrandB += uint64_t(Fi->m_SaveB); // saved once, not per run
		}
	}
	fprintf(OutFile, "\n%zu findings; up to %llu T-states per run and %llu bytes.\n", Sorted.size(),
		(unsigned long long)GrandT, (unsigned long long)GrandB);
	if (!StruckList.empty())
	{
		fprintf(OutFile, "%zu further finding(s) struck as unsafe.\n", StruckList.size());
	}

	fprintf(OutFile, "\n'link' says how fragile a finding is.\n"
					 "  in/N    single-instruction rule: control reached this site N distinct\n"
					 "          ways, and 'held' says the pattern was true on every one of\n"
					 "          them. N is how many entry paths you would check before acting.\n"
					 "  adj     pair rule, the two fall through in memory -- edit both lines.\n"
					 "  path/1  not adjacent, but across the whole run the second\n"
					 "          instruction had exactly ONE predecessor: this path is the\n"
					 "          only way in, so the work really is unnecessary. Acting on it\n"
					 "          means moving code, not just deleting a line.\n"
					 "  path/N  N distinct predecessors were seen. The pattern held on the\n"
					 "          path taken here, but other entries exist -- check them.\n");

	fprintf(
		OutFile, "\n%-22s %9s %7s %8s %9s %8s  %s\n", "site", "runs", "held", "link", "T saved", "bytes", "suggestion");
	for (const Finding* Fi : Sorted)
	{
		const uint64_t Execs = SiteExecCount(Fi);

		std::string Label;
		if (m_Symbols != nullptr && !BinaryTrace::PageTagIsRom(Fi->m_Page))
		{
			std::string L;
			if (m_Symbols->LookupNearest(Fi->m_Page, Fi->PC, 256, L))
			{
				Label = L;
			}
		}

		char Site[32];
		snprintf(Site, sizeof(Site), "%u:$%04X", Fi->m_Page, Fi->PC);

		// Single-instruction rules have nothing to link. Pair rules report the
		// fall-through case as `adj`, and otherwise how many distinct ways the
		// second instruction was reached across the whole run.
		char Link[16] = "--";
		if (!Fi->m_bPair)
		{
			// Single-instruction rules: how many distinct ways control reached
			// this site. `held` already says the pattern was true on every
			// execution; this says how many entries had to agree for that, i.e.
			// how many places you would have to check before acting.
			const auto SIt = m_PredCount.find(SiteOf(Fi->m_Page, Fi->PC));
			snprintf(Link, sizeof(Link), "in/%u", (SIt != m_PredCount.end()) ? SIt->second : 1u);
		}
		else
		{
			if (Fi->m_bAllAdj)
			{
				snprintf(Link, sizeof(Link), "adj");
			}
			else
			{
				const auto PIt = m_PredCount.find(Fi->m_Partner);
				const uint32_t N = (PIt != m_PredCount.end()) ? PIt->second : 1;
				snprintf(Link, sizeof(Link), "path/%u", N);
			}
		}

		fprintf(OutFile, "%-22s %9llu %6.0f%% %8s %9lld %8d  %s%s\n", Site, (unsigned long long)Execs,
			Execs ? 100.0 * double(Fi->m_Hits) / double(Execs) : 100.0, Link,
			(long long)(int64_t(Fi->m_Hits) * Fi->m_SaveT), int(Fi->m_SaveB), Fi->m_Text.c_str(), "");
		if (!Label.empty())
		{
			fprintf(OutFile, "%-22s %s\n", "", Label.c_str());
		}
	}

	// What was suppressed, and on what evidence.
	if (!StruckList.empty())
	{
		fprintf(OutFile,
			"\nstruck as unsafe (%zu) -- listed so a suppressed finding is never\n"
			"mistaken for no finding:\n",
			StruckList.size());
		for (const Struck& S : StruckList)
		{
			char Site[32];
			snprintf(Site, sizeof(Site), "%u:$%04X", S.m_F->m_Page, S.m_F->PC);
			if (S.m_Byte >= 0)
			{
				fprintf(OutFile, "  %-16s $%04X written  %s\n", Site, unsigned(S.m_F->PC + S.m_Byte),
					S.m_F->m_Text.c_str());
			}
			else
			{
				fprintf(OutFile, "  %-16s %-14s %s\n", Site, S.m_Why, S.m_F->m_Text.c_str());
			}
		}
	}

	// Per-rule totals, so it is obvious which KIND of change is worth a pass.
	fprintf(OutFile, "\nby rule:\n");
	for (int R = 0; R < kRuleIdRuleCount; ++R)
	{
		uint64_t T = 0, B = 0, N = 0;
		for (const Finding* Fi : Sorted)
		{
			if (Fi->m_Rule != R)
			{
				continue;
			}
			if (Fi->m_SaveT > 0)
			{
				T += Fi->m_Hits * uint64_t(Fi->m_SaveT);
			}
			if (Fi->m_SaveB > 0)
			{
				B += uint64_t(Fi->m_SaveB);
			}
			++N;
		}
		if (N == 0)
		{
			continue;
		}
		fprintf(OutFile, "  %-52s %4llu sites %10llu T %6llu bytes\n", kRuleName[R], (unsigned long long)N,
			(unsigned long long)T, (unsigned long long)B);
	}

	fclose(OutFile);
	return true;
}

#endif // INSPECCY_TRACE_SUPPORT
